INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c9481ff25beb440b1d9b','AMEDEX 2025 OBS  (1).pdf','15','Obstetrics','A 28-year-old woman is admitted to the
Maternity Unit in early labor. She has had an
uncomplicated pregnancy to date and is
otherwise healthy. She asks you about fetal
monitoring during labor and says she has heard
that cardiotocography (CTG) is helpful for the
assessment of the baby’s well-being and
preventing fetal problems. In counseling
regarding the use of CTG as a predictor of fetal
outcome and satisfactory labor in comparison to
intermittent auscultation and whether CTG
monitoring will reduce the risk of neonatal
developmental abnormalities, which one of the
following would be the most appropriate advice?','{"A":"There is no evidence to support admission CTG.","B":"CTG is a predictor of previous fetal oxygenation.","C":"Compared to intermittent auscultation, CTG is superior in monitoring the baby''s wellbeing.","D":"CTG is a good predictor of the fetal outcome.","E":"CTG will reduce the risk of neonatal developmental abnormalities."}','A',NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-0bd1e652917d","duplicate_sources":[{"record_id":"c9481ff25beb440b1d9b","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":15,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c9481ff25beb440b1d9b","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":15,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 28-year-old woman is admitted to the\nMaternity Unit in early labor. She has had an\nuncomplicated pregnancy to date and is\notherwise healthy. She asks you about fetal\nmonitoring during labor and says she has heard\nthat cardiotocography (CTG) is helpful for the\nassessment of the baby’s well-being and\npreventing fetal problems. In counseling\nregarding the use of CTG as a predictor of fetal\noutcome and satisfactory labor in comparison to\nintermittent auscultation and whether CTG\nmonitoring will reduce the risk of neonatal\ndevelopmental abnormalities, which one of the\nfollowing would be the most appropriate advice?","options":{"A":"There is no evidence to support admission CTG.","B":"CTG is a predictor of previous fetal o