INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4001faefad9dff04ad2b','AMEDEX 2025 OBS  (1).pdf','20','Obstetrics','A 30-year-old woman presents to the
emergency department at 37 weeks of
pregnancy after the sudden onset of severe
abdominal pain, vaginal bleeding
(approximately 1200 cc), and cessation of
contractions after 18 hours of active pushing
at home. The pregnancy has been uneventful
otherwise. On examination, she is conscious
and pale, with a blood pressure of 70/45
mmHg and a pulse rate of 115 bpm. The
abdomen is irregularly distended. Shifting
dullness and fluid thrill are present. Fetal
heart sounds are not audible. Which one of
the following is the most likely diagnosis?','{"A":"A Placenta previa.","B":"B Placental abruption.","C":"c Uterine rupture.","D":"D Cervical laceration.","E":"— Disseminated intravascular\ncoagulation."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[20],"source_qid":null,"duplicate_group_id":"exact-3006b4502919","duplicate_sources":[{"record_id":"4001faefad9dff04ad2b","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":20,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4001faefad9dff04ad2b","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":20,"supporting_pages":[20],"source_qid":null,"domain_hint":"Obstetrics","stem":"A 30-year-old woman presents to the\nemergency department at 37 weeks of\npregnancy after the sudden onset of severe\nabdominal pain, vaginal bleeding\n(approximately 1200 cc), and cessation of\ncontractions after 18 hours of active pushing\nat home. The pregnancy has been uneventful\notherwise. On examination, she is conscious\nand pale, with a blood pressure of 70/45\nmmHg and a pulse rate of 115 bpm. The\nabdomen is irregularly distended. Shifting\ndullness and fluid thrill are present. Fetal\nheart sounds are not audible. Which one of\nthe following is the most likely diagnosis?","options":{"A":"A Placenta previa.","B":"B Placental abruption.","C":"c Uterine rupture.","D":"D Cervical laceration.","E":"— Disseminated intravascular\ncoagulation."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answ