INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d3d6be484cc94ede0cb0','AMEDEX 2025 OBS  (1).pdf','23','Obstetrics','A 27-year-old pregnant woman presents to
your practice in the first trimester of her
pregnancy for routine antenatal care. On
investigations, she is found to be positive
for hepatitis C virus antibody (HCVAb). On
discussing the matter with her, she becomes
extremely concerned about the transmission
of the disease to her baby. Which one of the
following is correct about the condition?','{"A":"Cesarean section can prevent the\ntransmission.","B":"Fetal scalp blood sampling should\nbe avoided.","C":"Breastfeeding is contraindicated\nfor her.","D":"The baby should be screened for\nhepatitis C shortly after delivery.","E":"The co-existence of HIV has no\neffect on HCV transmission."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9dc45901a21d","duplicate_sources":[{"record_id":"d3d6be484cc94ede0cb0","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":23,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d3d6be484cc94ede0cb0","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":23,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 27-year-old pregnant woman presents to\nyour practice in the first trimester of her\npregnancy for routine antenatal care. On\ninvestigations, she is found to be positive\nfor hepatitis C virus antibody (HCVAb). On\ndiscussing the matter with her, she becomes\nextremely concerned about the transmission\nof the disease to her baby. Which one of the\nfollowing is correct about the condition?","options":{"A":"Cesarean section can prevent the\ntransmission.","B":"Fetal scalp blood sampling should\nbe avoided.","C":"Breastfeeding is contraindicated\nfor her.","D":"The baby should be screened for\nhepatitis C shortly after delivery.","E":"The co-existence of HIV has no\neffect on HCV transmission."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"9dc45901a21d832cb9b48bc345dbeeb987b23a0c","duplicate_group_id":"exact-9dc45901a21d","duplicate_sources":[{"record_id":"d3d6be484cc94ede0cb0","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":23,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
