INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dea8a7acd07981de7520','AMEDEX 2025 OBS  (1).pdf','28','Obstetrics','A 27-year-old woman comes to the antenatal
clinic at ten weeks gestation. It is her first
pregnancy. She smokes two packs of
cigarettes a day and drinks 5-7 standard
drinks every day. Recently, she has started
using crack cocaine and heroin. She mentions
that she is going through a lot these days
because her employer found out about her
addiction and fired her. She is very anxious
and worried about her future and cannot
Sleep well. This is why she uses diazepam
every night. Which of the following in history
may have the worst effect on the fetus?','{"A":"Cocaine.","B":"Heroin.","C":"Cigarette smoking.","D":"Diazepam.","E":"Alcohol."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-2c55c5658393","duplicate_sources":[{"record_id":"dea8a7acd07981de7520","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":28,"source_qid":null},{"record_id":"f7dddba4efbc2a69b10c","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":27,"source_qid":null},{"record_id":"0e4961221fbcafe6a343","record_type":"text_mcq","source_file":"Obstetrics and Gynaecology Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Obstetrics and Gynaecology Amedex 2025.pdf","source_page":551,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"dea8a7acd07981de7520","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":28,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 27-year-old woman comes to the antenatal\nclinic at ten weeks gestation. It is her first\npregnancy. She smokes two packs of\ncigarettes a day and drinks 5-7 standard\ndrinks every day. Recently, she has started\nusing crack cocaine and heroin. She mentions\nthat she is going through a lot these days\nbecause her employer found out about her\naddiction and fired her. She is very anxious\nand worried about her future and cannot\nSleep well. This is why she uses diazepam\nevery night. Which of the following in history\nmay have the worst effect on the fetus?","options":{"A":"Cocaine.","B":"Heroin.","C":"Cigarette smoking.","D":"Diazepam.","E":"Alcohol."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"2c55c565839398d6de08ac23119d8c49b0337d26","duplicate_group_id":"exact-2c55c5658393","duplicate_sources":[{"record_id":"dea8a7acd07981de7520","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":28,"source_qid":null},{"record_id":"f7dddba4efbc2a69b10c","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":27,"source_qid":null},{"record_id":"0e4961221fbcafe6a343","record_type":"text_mcq","source_file":"Obstetrics and Gynaecology Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Obstetrics and Gynaecology Amedex 2025.pdf","source_page":551,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,r