INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a6b5fd82d5b1183884f7','AMEDEX 2025 OBS  (1).pdf','31','Obstetrics','A 31-year-old G2P1 woman presented to the
maternity unit at 38 weeks gestation and in
labour. Her previous pregnancy led toa
cesarean section and the delivery of a healthy
baby. The current pregnancy had been
uneventful, without any remarkable problems
in antenatal visits except for first-trimester
nausea and vomiting. On arrival, she had a
cervical dilation of 4 cm, and the fetal head
was at -1 Station. After five hours, the cervical
length and fetal head station remain the
Same despite regular uterine contractions.
Suddenly, there is a sudden gush of blood of
approximately 1000 mL, and the fetal heart
rate drops to 80 bpm on CTG. Which of the
