INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ad866ef08413105e5a5b','AMEDEX 2025 OBS  (1).pdf','32','Obstetrics','A 31-year-old G2P1 woman presented to the
maternity unit at 38 weeks gestation and in
labour. Her previous pregnancy led to a
cesarean section and the delivery of a healthy
baby. The current pregnancy had been
uneventful, without any remarkable problems
in antenatal visits except for first-trimester
nausea and vomiting. On arrival, she had a
cervical dilation of 4 cm, and the fetal head
was at -1 station. After five hours, the cervical
length and fetal head station remain the
Same despite regular uterine contractions.
Suddenly, there is a sudden gush of blood of
approximately 1000 mL, and the fetal heart
rate drops to 80 bpm on CTG. Which of the
following could be the most likely cause?','{"A":"Lower genital tract lacerations.","B":"Placenta previa.","C":"Placenta accreta.","D":"Uterine atony.","E":"— Ruptured uterus."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-cb4b870b36fa","duplicate_sources":[{"record_id":"ad866ef08413105e5a5b","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":32,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"ad866ef08413105e5a5b","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":32,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 31-year-old G2P1 woman presented to the\nmaternity unit at 38 weeks gestation and in\nlabour. Her previous pregnancy led to a\ncesarean section and the delivery of a healthy\nbaby. The current pregnancy had been\nuneventful, without any remarkable problems\nin antenatal visits except for first-trimester\nnausea and vomiting. On arrival, she had a\ncervical dilation of 4 cm, and the fetal head\nwas at -1 station. After five hours, the cervical\nlength and fetal head station remain the\nSame despite regular uterine contractions.\nSuddenly, there is a sudden gush of blood of\napproximately 1000 mL, and the fetal heart\nrate drops to 80 bpm on CTG. Which of the\nfollowing could be the most likely cause?","options":{"A":"Lower genital tract lacerations.","B":"Placenta previa.","C":"Placenta accreta.","D":"Uterine atony.","E":"— Ruptured uterus."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","c