INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2e04ef8a1951bd398e7e','AMEDEX 2025 OBS  (1).pdf','36','Obstetrics','Robert and Janet are in your clinic for
consultation. Robert complains of malaise, mild
headache, and a generalized rash in the form of
both intact and unroofed vesicles, as well as
macules and papules. Three weeks ago, Alan,
their 7-year-old, was diagnosed with
chickenpox. Based on the history and the
appearance of the rash, you make a diagnosis
of chickenpox for Robert. Janet is 13 weeks
pregnant and is concerned if the infection can
affect her and her baby, too. Janet is not sure if
she had chickenpox in childhood. Which of the
following is the most appropriate next step in
the management of Janet?','{"A":"Start her on oral acicolvir.","B":"Give her varicella zoster vaccine\n(Varivax).","C":"Give her varicella zoster\nimmunoglobulin (VZIG).","D":"Arrange for checking her varicella\nzoster antibody (IgG) status.","E":"Start her on oral famcilovir. ©"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-b84278297052","duplicate_sources":[{"record_id":"2e04ef8a1951bd398e7e","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":36,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"2e04ef8a1951bd398e7e","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":36,"source_qid":null,"domain_hint":"Obstetrics","stem":"Robert and Janet are in your clinic for\nconsultation. Robert complains of malaise, mild\nheadache, and a generalized rash in the form of\nboth intact and unroofed vesicles, as well as\nmacules and papules. Three weeks ago, Alan,\ntheir 7-year-old, was diagnosed with\nchickenpox. Based on the history and the\nappearance of the rash, you make a diagnosis\nof chickenpox for Robert. Janet is 13 weeks\npregnant and is concerned if the infection can\naffect her and her baby, too. Janet is not sure if\nshe had chickenpox in childhood. Which of the\nfollowing is the most appropriate next step in\nthe management of Janet?","options":{"A":"Start her on oral acicolvir.","B":"Give her varicella zoster vaccine\n(Varivax).","C":"Give her varicella zoster\nimmunoglobulin (VZIG).","D":"Arrange for checking her varicella\nzoster antibody (IgG) sta