INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('89f3816d7c6dfc3f0c85','AMEDEX 2025 OBS  (1).pdf','40','Obstetrics','A 27-year-old woman presents to the primary
care center where you work at 26 weeks
gestation after she has been noticing
intermittent leakage of watery liquor per
vagina for the past eight hours, especially
after straining, coughing, or sneezing. You
perform a speculum vaginal exam which
reveals clear fluid in the posterior vaginal
fornix, as well as a flow of liquid through the
cervical os. Further evaluation, establishes
preterm premature rupture of the
membranes (PPROM) as the diagnosis. No
uterine contraction is felt. There is a tertiary
hospital 50 km away. Which one of the
following is the most appropriate next step in
management?','{"A":"yv ( )A_ Administration corticosteroids.","B":"Commencement of tocolysis.","C":"Transferring her to the tertiary\nhospital.","D":"Sending her home on oral\nantibiotics and warning signs.","E":"— Admission for observation. ©"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-f973d2eeceb1","duplicate_sources":[{"record_id":"89f3816d7c6dfc3f0c85","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":40,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"89f3816d7c6dfc3f0c85","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":40,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 27-year-old woman presents to the primary\ncare center where you work at 26 weeks\ngestation after she has been noticing\nintermittent leakage of watery liquor per\nvagina for the past eight hours, especially\nafter straining, coughing, or sneezing. You\nperform a speculum vaginal exam which\nreveals clear fluid in the posterior vaginal\nfornix, as well as a flow of liquid through the\ncervical os. Further evaluation, establishes\npreterm premature rupture of the\nmembranes (PPROM) as the diagnosis. No\nuterine contraction is felt. There is a tertiary\nhospital 50 km away. Which one of the\nfollowing is the most appropriate next step in\nmanagement?","options":{"A":"yv ( )A_ Administration corticosteroids.","B":"Commencement of tocolysis.","C":"Transferring her to the tertiary\nhospital.","D":"Sending her home on oral\nantibiotics and warning signs.","E":"— Admis