INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6fc86cd43fbe38b605dd','AMEDEX 2025 OBS  (1).pdf','44','Obstetrics','Antibiotic prophylaxis is indicated in all women
with PPROM after low and high vaginal swabs
are taken. In the absence of chorioamnionitis,
the recommended antibiotic prophylaxis of
choice is erythromycin, given for 10 days
intravenously.
Chorioamnionitis is a feared complication of
PPROM. The diagnosis of chorioamnionitis relies
on the clinical presentation and may be difficult
in its early manifestations. The clinical picture
may include maternal fever with 2 or more of
the following:
