presents with regular uterine contractions.
Cardiotocography shows the presence of a
live fetus with regular accelerations. Blood
pressure is 200/120 mmHg. Liver function
tests show mildly raised serum alkaline
phosphatase. Sterile soeculum examination
shows foul-smelling fluid leakage from the
vagina. Which one of the following is the next
best step in this situation?','{"A":"Suppression of labor by giving oral\nnifedipine with two further doses if\ncontractions still persist.","B":"Intravenous salbutamol should be\nused as a first-line drug to stop\nuterine contractions.","C":"Both nifedipine and salbutamol are\nindicated in this patient.","D":"Further investigations are needed\nto find whether this patient needs\ntocolysis.","E":"Tocolysis is absolutely\ncontraindicated in this patient"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-fab44221f533","duplicate_sources":[{"record_id":"6b9d450dc70e7bf465c8","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":94,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"6b9d450dc70e7bf465c8","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":94,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 29-year-old woman at 32 weeks gestation\npresents with regular uterine contractions.\nCardiotocography shows the presence of a\nlive fetus with regular accelerations. Blood\npressure is 200/120 mmHg. Liver function\ntests show mildly raised serum alkaline\nphosphatase. Sterile soeculum examination\nshows foul-smelling fluid leakage from the\nvagina. Which one of the following is the next\nbest step in this situation?","options":{"A":"Suppression of labor by giving oral\nnifedipine with two further doses if\ncontractions still persist.","B":"Intravenous salbutamol should be\nused as a first-line drug to stop\nuterine contractions.","C":"Both nifedipine and salbutamol are\nindicated in this patient.","D":"Further investigations are needed\nto find whether this patient needs\ntocolysis.","E":"Tocolysis is absolutely\ncontraindicated in this patient"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"fab44221f5332710dcff7578cb7c6b9f33bda82b","duplicate_group_id":"exact-fab44221f533","duplicate_sources":[{"record_id":"6b9d450dc70e7bf465c8","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":94,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
