INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c9cbfa61b7accdbf9b7f','AMEDEX 2025 OBS  (1).pdf','129','Obstetrics','CTPA
The fetal radiation dose of CTPA is 0.000003-
0.000131 Gy. Although the radiation dose to the
fetus is lower in CTPA compared to V/Q scanning,
CTPA produces higher levels of radiation exposure
to women''s breasts.
Breast cancer risk in 20-year-old women after a
CTPA is estimated to be one event in 143
exposures, with a lifetime attributable risk of 0.7%.
The risk for malignancy is inversely related to age
at the time of exposure. Therefore, it is
recommended that women use breast shields
when undergoing CTPA to decrease radiation dose
from 0.05-0.08 Gy to 0.02-0.06 Gy.
A major benefit of CTPA over other imaging
modalities is that it often provides alternative
diagnoses. Thus far, no studies have addressed
the accuracy or outcome of CTPA in pregnant
patients. However, technical limitations might
produce poor vessel opacification in pregnant
patients that simulates PE and leads to false-
positive results. This appears to be more common
when apparent subsegmental PEs are identified.
Hence, it is usually recommended that
subsegmental PEs identified on CTPA be
confirmed with further testing (e.g., VQ scan or
lower extremity ultrasonography) before making a
final diagnosis.
Which test to choose?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","supporting_pages":[129],"source_qid":null,"duplicate_group_id":"exact-fdd96da54955","duplicate_sources":[{"record_id":"c9cbfa61b7accdbf9b7f","record_type":"visual_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":129,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/AMEDEX_2025_OBS_1__b68fb85caa97/page_00129.jpg","asset_preview_url":"https://drive.google.com/file/d/12rrOKeFpQLbhgjL09W9fjEXK1Tgkh1wA/preview"}','visual_assets/AMEDEX_2025_OBS_1__b68fb85caa97/page_00129.jpg','https://drive.google.com/thumbnail?id=12rrOKeFpQLbhgjL09W9fjEXK1Tgkh1wA&sz=w1600','source_page_image',NULL,'needs_verification','[]','high','{"record_id":"c9cbfa61b7accdbf9b7f","record_type":"visual_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_year":2025,"source_page":129,"supporting_pages":[129],"source_qid":null,"domain_hint":"Obstetrics","stem":"CTPA\nThe fetal radiation dose of CTPA is 0.000003-\n0.000131 Gy. Although the radiation dose to the\nfetus is lower in CTPA compared to V/Q scanning,\nCTPA produces higher levels of radiation exposure\nto women''s breasts.\nBreast cancer risk in 20-year-old women after a\nCTPA is estimated to be one event in 143\nexposures, with a lifetime attributable risk of 0.7%.\nThe risk for malignancy is inversely related to age\nat the time of exposure. Therefore, it is\nrecommended that women use breast shields\nwhen undergoing CTPA to decrease radiation dose\nfrom 0.05-0.08 Gy to 0.02-0.06 Gy.\nA major benefit of CTPA over other imaging\nmodalities is that it often provides alternative\ndiagnoses. Thus far, no studies have addressed\nthe accuracy or outcome of CTPA in pregnant\npatients. However, technical limitations might\nproduce poor vessel opacification in pregnant\npatients that simulates PE and leads to false-\npositive results. This appears to be more common\nwhen apparent subsegmental PEs are identified.\nHence, it is usually recommended that\nsubsegmental PEs identified on CTPA be\nconfirmed with further testing (e.g., VQ scan or\nlower extremity ultrasonography) before making a\nfinal diagnosis.\nWhich test to choose?","options":{},"options_mode":"source_page_image","visual_asset":"visual_assets/AMEDEX_2025_OBS_1__b68fb85caa97/page_00129.jpg","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","dose","pregnan"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"fdd96da54955a38d6715ef8bf5f46434f00b518f","duplicate_group_id":"exact-fdd96da54955","duplicate_sources":[{"record_id":"c9cbfa61b7accdbf9b7f","record_type":"visual_mcq","source_file":"AMEDEX 2025 OBS  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (1).pdf","source_page":129,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evi