INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('346c2bc430d3643ef7f6','AMEDEX 2025 OBS  (1).pdf','132','Obstetrics','A pregnant woman has come to you because
two days after babysitting her friend’s son, he
was diagnosed with infectious
mononucleosis. She is worried about herself
