INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f2b472ed285e93f16737','AMEDEX 2025 OBS  (4).pdf','14','Obstetrics','A 2/-year-old woman is in labour at 39 weeks
gestation when the passage of meconium is
noted. A cardiotocography (CTG) is arranged
that shows a fetal heart rate (FHR) of 149 bpm,
a beat-to-beat variability of 15, no acceleration,
and no deceleration. Which one of the following
should be the next best step in management?','{"A":"Fetal scalp blood sampling as there\nis a 10% chance of hypoxia.","B":"Fetal scalp blood sampling as there\nis a 50% chance of hypoxia.","C":"Fetal scalp blood sampling as there\nis 75% chance of hypoxia.","D":"Emergency cesarean section.","E":"Close monitoring until delivery as\nthere is no abnormality."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-fb85c41f0803","duplicate_sources":[{"record_id":"f2b472ed285e93f16737","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":14,"source_qid":null},{"record_id":"0fd7f7ffd2eff59a1355","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":15,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"f2b472ed285e93f16737","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_year":2025,"source_page":14,"source_qid":null,"domain_hint":"Obstetrics","stem":"A 2/-year-old woman is in labour at 39 weeks\ngestation when the passage of meconium is\nnoted. A cardiotocography (CTG) is arranged\nthat shows a fetal heart rate (FHR) of 149 bpm,\na beat-to-beat variability of 15, no acceleration,\nand no deceleration. Which one of the following\nshould be the next best step in management?","options":{"A":"Fetal scalp blood sampling as there\nis a 10% chance of hypoxia.","B":"Fetal scalp blood sampling as there\nis a 50% chance of hypoxia.","C":"Fetal scalp blood sampling as there\nis 75% chance of hypoxia.","D":"E