INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1a45cbca8b4c30b1393e','AMEDEX 2025 OBS  (4).pdf','20','Obstetrics','A 28-year-old woman, who is 22 weeks
pregnant in her second pregnancy, presents
for evaluation of a vulval ulcer. The swab
taken confirms the diagnosis of herpes
Simplex type II (HSV-II) infection. When she is
informed, she becomes quite surprised as
neither she nor her husband has ever had
this infection before and insists on knowing
the source of the infection. Furthermore, she
is very concerned about her baby’s well-being
and asks whether her condition may affect it.
Which of the following is the most
appropriate advice in this regard?','{"A":"Most neonates with neonatal\nherpes present with\nmucocutaneous lesions.","B":"Although treatment with antiviral\nagents such as aciclovir will reduce\nthe rate of recurrence of the\ndisease, they cannot be used\nduring pregnancy because of their\nadverse effects on the fetus.","C":"The primary infection is commonly\nasymptomatic.","D":"Unless she has had a new sexual\npartner recently, this problem\ncould not have been acquired\nsexually.","E":"risk of neonatal herpes is much\nhigher with recurrent maternal\ninfection compared with primary\ninfection."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","supporting_pages":[20,21],"source_qid":null,"duplicate_group_id":"exact-8c8bbf190812","duplicate_sources":[{"record_id":"1a45cbca8b4c30b1393e","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":20,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"1a45cbca8b4c30b1393e","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_year":2025,"source_page":20,"supporting_pages":[20,21],"source_qid":null,"domain_hint":"Obstetrics","stem":"A 28-year-old woman, who is 22 weeks\npregnant in her second pregnancy, presents\nfor evaluation of a vulval ulcer. The swab\ntaken confirms the diagnosis of herpes\nSimplex type II (HSV-II) infection. When she is\ninformed, she becomes quite surprised as\nneither she nor her husband has ever had\nthis infection before and insists on knowing\nthe source of the infection. Furthermore, she\nis very concerned about her baby’s well-being\nand asks whether her condition may affect it.\nWhich of the following is the most\nappropriate advice in this regard?","options":{"A":"Most neonates with neonatal\nherpes present with\nmucocutaneous lesions.","B":"Although treatment with antiviral\nagents such as aciclovir will reduce\nthe rate of recurrence of the\ndisease, they cannot be used\nduring pregnancy because of their\nadverse effects on the fetus.","C":"The primary infection is commonly\nasymptomatic.","D":"Unless she has had a new sexual\npartner recently, this problem\ncould not have been acquired\nsexually.","E":"risk of neonatal herpes is much\nhigher with recurrent maternal\ninfection compared with primary\ninfection."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"8c8bbf190812989ec6f7a4bca258d21d5dce664a","duplicate_group_id":"exact-8c8bbf190812","duplicate_sources":[{"record_id":"1a45cbca8b4c30b1393e","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":20,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=