INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0e64d5d0a7256aeb3f99','AMEDEX 2025 OBS  (4).pdf','80','Obstetrics','Trang undergoes an elective cesarean section
at 38 weeks gestation under general
anesthesia. As soon as the baby is out, her
blood pressure drops from 117/78 mmHg to
91/55 mmHg, and her heart rate increases to
