INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fbe0413f3809989e2f0b','AMEDEX 2025 OBS  (4).pdf','148','Obstetrics','Mary, 33 years old, presents to the Maternity
Unit for delivery at 38 weeks gestation. She
has had all her antenatal visits until now, but
there is no record of Group B streptococcus
(GBS) status in her file. When you discuss the
issue with her, you learn that her general
practitioner failed to take swabs for culture.
Mary has a 3-year-old son, Michael, who
suffered an early GBS sepsis shortly after
birth but survived and enjoys good health
now. Mary’s current pregnancy has been
uneventful until now. Which of the following
is the most appropriate next step in
management?','{"A":"Do vaginal swab for GBS now.","B":"Give antibiotics during the labor.","C":"Give prophylactic antibiotics to the\nbaby immediately after the\ndelivery.","D":"Ask her general practitioner why he\nhas not performed the swabs.","E":"Refer the matter to the Medica\nBoard."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-dedad32a0c38","duplicate_sources":[{"record_id":"fbe0413f3809989e2f0b","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":148,"source_qid":null},{"record_id":"d82d0abeff836f775bd4","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":149,"source_qid":null},{"record_id":"9a65de38f4d162640022","record_type":"text_mcq","source_file":"Obstetrics and Gynaecology Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Obstetrics and Gynaecology Amedex 2025.pdf","source_page":469,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"fbe0413f3809989e2f0b","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_year":2025,"source_page":148,"source_qid":null,"domain_hint":"Obstetrics","stem":"Mary, 33 years old, presents to the Maternity\nUnit for delivery at 38 weeks gestation. She\nhas had all her antenatal visits until now, but\nthere is no record of Group B streptococcus\n(GBS) status in her file. When you discuss the\nissue with her, you learn that her general\npractitioner failed to take swabs for culture.\nMary has a 3-year-old son, Michael, who\nsuffered an early GBS sepsis shortly after\nbirth but survived and enjoys good health\nnow. Mary’s current pregnancy has been\nuneventful until now. Which of the following\nis the most appropriate next step in\nmanagement?","options":{"A":"Do vaginal swab for GBS now.","B":"Give antibiotics during the labor.","C":"Give prophylactic antibiotics to the\nbaby immediately after the\ndelivery.","D":"Ask her general practitioner why he\nhas not performed the swabs.","E":"Refer the matter to the Medica\nBoard."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"dedad32a0c38b7f5abd26974fa501742d634d8c5","duplicate_group_id":"exact-dedad32a0c38","duplicate_sources":[{"record_id":"fbe0413f3809989e2f0b","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":148,"source_qid":null},{"record_id":"d82d0abeff836f775bd4","record_type":"text_mcq","source_file":"AMEDEX 2025 OBS  (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 OBS  (4).pdf","source_page":149,"source_qid":null},{"record_id":"9a65de38f4d162640022","record_type":"text_mcq","source_file":"Obstetrics and Gynaecology Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Obstetrics and Gynaecology Amedex 2025.pdf","source_page":469,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=exc